{"sql": "CREATE OR REPLACE FUNCTION public.get_user_theme_id()
RETURNS INTEGER AS $$
BEGIN
    IF current_user = 'theme_analyst' THEN
        RETURN 18; -- Star Wars theme
    ELSE
        RETURN NULL; -- No theme restriction for other users
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;"}

