{"sql": "DROP FUNCTION IF EXISTS public.get_user_theme_id();
CREATE OR REPLACE FUNCTION public.get_user_theme_id()
RETURNS INTEGER AS $$
DECLARE
    user_theme_id INTEGER;
BEGIN
    SELECT CASE 
        WHEN CURRENT_USER = 'theme_analyst' THEN 18
        ELSE NULL
    END INTO user_theme_id;

    RETURN user_theme_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;"}

